// Met auto-open-disabled opent de modal niet vanzelf bij het laden. open() toont hem, ook als de gebruiker zijn
// keuze al bewaarde.
document.querySelector('#button-open-cookie-consent').addEventListener('click', () => {
    document.querySelector('#cookie-consent').open();
});

// vl-cookie-consent vuurt vl-close af nadat de modal gesloten is.
document.querySelector('#cookie-consent').addEventListener('vl-close', () => console.log('vl-close'));
